import { readArtifact, writeArtifact } from './event-store.js';
import { checkAbort } from './client.js';

// Lifetime W/L costs one packed word per 32 days on a cold browser. Once
// cached, only the unfinished word and new days are read. No global log scan.
// CoinflipCore processes each epoch once in order; _storeDayResult changes
// only that day's 8-bit lane. A word ending at day 31 mod 32 is closed once
// flipsClaimableDay reaches it. The current partial word must stay live.
const WORDS_PER_CHUNK = 4;
const closedChunkFlights = new Map();

function closedWords(s, key, base, count) {
  if (!count) return Promise.resolve([]);
  const id = `${key}:${base}:${count}`;
  const pending = closedChunkFlights.get(id);
  // Closed words never change on canonical history. A replacement route can
  // share reads still queued by its expired predecessor instead of queuing
  // the same words again at a newer block. Never borrow a future snapshot.
  if (pending && pending.snapshot.block.number <= s.block.number) return pending.promise;
  const flight = { snapshot: s, promise: null };
  flight.promise = (async () => {
    const words = await Promise.all(Array.from({ length: count },
      (_, i) => s.field('COINFLIP', 'coinflipDayResultPacked', base + i)));
    // This proof belongs to the shared work, independently of its first
    // consumer's deadline. Failed/reorganized reads never become reusable.
    await s.verify();
    return words;
  })().finally(() => {
    if (closedChunkFlights.get(id) === flight) closedChunkFlights.delete(id);
  });
  closedChunkFlights.set(id, flight);
  return flight.promise;
}

export async function coinflipStats(s, signal) {
  const last = Number(await s.field('COINFLIP', 'flipsClaimableDay'));
  const key = `flip-record:${s.client.chain.id}:${s.client.address('COINFLIP')}`;
  let saved = await readArtifact(key);
  const header = number => s.header ? s.header(number, signal) : s.client.header(number, signal);
  if (saved && (saved.throughDay > last || saved.block > s.block.number
    || (await header(saved.block)).hash !== saved.hash)) saved = null;
  let wins = saved?.wins ?? 0, losses = saved?.losses ?? 0, recent = saved?.recent ?? [];
  const first = (saved?.throughDay ?? 0) + 1;
  for (let base = first >> 5; base <= (last >> 5); base += WORDS_PER_CHUNK) {
    checkAbort(signal);
    const count = Math.min(WORDS_PER_CHUNK, (last >> 5) - base + 1);
    const closedCount = Math.min(count, Math.max(0, Math.floor((last + 1) / 32) - base));
    const [closed, live] = await Promise.all([
      closedWords(s, key, base, closedCount),
      Promise.all(Array.from({ length: count - closedCount },
        (_, i) => s.field('COINFLIP', 'coinflipDayResultPacked', base + closedCount + i))),
    ]);
    const words = [...closed, ...live];
    checkAbort(signal);
    let checkpoint = null;
    for (const [i, word] of words.entries()) {
      const start = Math.max(first, (base + i) * 32), end = Math.min(last, (base + i) * 32 + 31);
      for (let day = start; day <= end; day++) {
        const byte = Number(word >> BigInt((day & 31) * 8) & 255n);
        if (!byte) continue;
        const win = byte >= 50;
        if (win) wins++; else losses++;
        recent = [{ day, win, rewardPercent: byte }, ...recent].slice(0, 26);
      }
      if (end % 32 === 31) checkpoint = { throughDay: end, wins, losses, recent };
    }
    // Persist each verified prefix before requesting more. A 25-word cold
    // batch took longer than the route deadline under RPC backoff, discarded
    // every completed word, and restarted the same lifetime scan next poll.
    if (checkpoint) {
      await s.verify(signal);
      checkAbort(signal);
      writeArtifact(key, { ...checkpoint, block: s.block.number, hash: s.block.hash });
    }
  }
  return { wins, losses, recent };
}
